"""Proposed motion recipes and explicit placement decisions for the page atlas."""
MOTIONS=[]
def motion(key,name,asset,duration,effect,trigger,native,iterations=1):
 MOTIONS.append(dict(id=key,name=name,asset=asset,duration=duration,effect=effect,trigger=trigger,native=native,iterations=iterations,easing='cubic-bezier(0.22,1,0.36,1)'))
motion('M01','City assembles','G01',680,'Foreground, skyline and sun enter in staggered layers; no text delay.','Welcome/opening an idle city chapter','Animatable opacity/translation on three cached Canvas layers')
motion('M02','Taxi rolls into its frame','G02',1100,'Illustrated car glides 85 px and its drawn wheels turn, then park.','Welcome/idle illustration entry only','One normalized progress drives taxi offset and two wheel angles')
motion('M03','Ribbon writes itself','G04',820,'A curved brand ribbon draws from an anchored point into a settled emblem.','Opening journey review; actual route geometry is a separate resource','Cached PathMeasure segment with Animatable progress; final path immediate in reduced mode')
motion('M04','Location illustration settles','G16',420,'Decorative pointer scales 0.85 → 1.03 → 1 inside its reserved box.','Location rationale or point confirmation visual','Animatable scale with bounded spring; map pin/hit target does not move')
motion('M05','Calendar page turns','G15',520,'Calendar graphic tilts forward and rests; selected date text stays outside the art.','Actual date-selection change','graphicsLayer rotation/opacity; dates not embedded in animation')
motion('M06','Ticket opens','G05',460,'Receipt artwork reveals vertically while the fare and status are already readable.','Opening recorded trip/receipt','Canvas clip on illustration only; content outside the clip')
motion('M07','Documents fan out','G12',540,'Two sheets rotate slightly apart and settle into a folio.','Application step entry or actual document replacement acknowledgement','Two cached layers with independent rotation; no invented scan/approval tick')
motion('M08','Envelope greets','G18',560,'The illustrated letter rises once above its envelope then returns.','Empty inbox or notification rationale entry','Short local offset sequence; actual unread messages remain state-owned')
motion('M09','Coastal drift','G09',2400,'Horizon strokes move gently, with a static sun and fixed text.','Welcome decorative area while visible; limited replay','Canvas translation, maximum three cycles, cancelled when hidden',3)
motion('M10','Community gathers','G13',720,'Abstract people come together around a simple connection rhythm.','Cooperative information / onboarding introduction','Staggered layer translation and opacity; no live-member/supply implication')
motion('M11','Friendly object winks','G14',260,'An illustrated help object closes its eyes once; no typing indicator.','General Help entry, never a safety report or incident','Two eye shapes; one finite scaleY sequence; no character tracking password input')
motion('M12','Thank-you spark','G24',620,'A small check and four rays appear once and settle.','Only a suitable backend-confirmed outcome; never pending cash/claim','Path trim plus short radial opacity; no celebratory loop or financial count-up')
motion('M13','Notebook opens','G11',680,'A blank trip notebook tilts slightly open, then rests.','True empty history, not a failed/restricted read','Cached notebook layers; limited rotation; no fabricated entry or balance')
motion('M14','Light crosses the illustration','G22',900,'A softly bounded light sweep reveals a print texture inside the artwork area.','Welcome or a deliberate artwork hover/focus preview','Canvas clipping plus gradient offset; text and functional buttons have opaque fill')
motion('M15','Soft material press','G10',160,'A decorative object compresses slightly, retaining its fixed frame.','Intentional illustration interaction; button hitboxes remain fixed','Local scale/tone, press state from InteractionSource for real controls')
motion('M16','Selection highlight travels','G07',300,'A wash/arch moves a short distance between two contained positions.','A real local choice change, such as approved display preference','updateTransition on indicator offset/color; controlled selection remains authoritative')
motion('M17','Panels retain continuity','G21',260,'Cropped road bands enter with a short crossfade and 8 px translation.','Opening a console section or switching scoped content','AnimatedContent / AnimatedVisibility with stable record keys and safe scope clearing')
motion('M18','Indeterminate route weave','G04',1400,'A short band moves around a decorative ribbon while a request is genuinely pending.','Actual read/request in flight, with readable indeterminate copy','Animatable dash offset stopped on completion/failure; never suggests driver ETA',3)

def placement(p):
 key=p['id'];n=int(key[1:]);layout=p['layout'];prefix=key[0]
 # Sensitive/critical surfaces receive an intentional no-decoration decision.
 sensitive={'S06','S08','S15','S17','S18','S19','R36','R39','R40','D33','D39','D40','O01','O02','O35','O36','O49','O50','O53','O54','O57','O58','O59','O63','O64','O65','O70','O71','O73','O74','O85','O87'}
 if key in sensitive:return dict(asset=None,motion=None,slot='No illustration beside sensitive fields or consequential review',size='0 dp',condition='Task text and exact target retain the whole available area; normal focus/press feedback remains.')
 if p['deferred']:return dict(asset='G21',motion=None,slot='Proposal/capability chapter marker',size='24 dp header edge',condition='Static only; no active alpha navigation or implied capability.')
 if key in {'S02','A00'}:return dict(asset='G01',motion='M01',slot='Dedicated welcome illustration, separate from title and actions',size='160–220 dp high; can collapse to 96',condition='First visible entry only; illustrations never delay authentication controls.')
 if key in {'S00','S01','S09'}:return dict(asset='G21',motion='M18' if key=='S00' else None,slot='Small contained loading/gate emblem',size='40–56 dp',condition='Indeterminate only for a real pending read; errors/compatibility gates keep static context.')
 if key in {'S10','R01','R02','R03'}:return dict(asset='G16',motion='M04' if key=='S10' else None,slot='Rationale art / small point-selection header emblem',size='96 dp on rationale; 24–32 dp beside map title',condition='Operational map and confirmation remain clear; real map pin is stable.')
 if key in {'S11','R32','D31'}:return dict(asset='G18',motion='M08',slot='True empty inbox / permission rationale',size='80–112 dp; absent from populated list',condition='No decorative new-message/typing promise; real records keep normal list transitions.')
 if key in {'R00','R41'}:return dict(asset='G07',motion=None,slot='City title frame outside the map viewport',size='32–48 dp high',condition='City identity detail is static and does not become a decorative map overlay.')
 if key in {'R05','R06','R07','R15','R16','R25','R37','D16','D17','D18'}:return dict(asset='G04',motion='M03' if key=='R05' else None,slot='Small abstract journey emblem or chapter edge',size='24–40 dp',condition='Animation on review entry only; active travel/reviews stay still; actual directions not replaced.')
 if key in {'R08','R09'}:return dict(asset='G04',motion='M18',slot='Contained indeterminate request emblem',size='48–64 dp',condition='Only during a genuine pending request; explicit matching text, no completion percentage or taxi simulation.')
 if key in {'R10','R22','D25'}:return dict(asset='G11',motion='M13',slot='True empty/unmatched illustration above useful action',size='96–128 dp; collapse at large text',condition='Empty-history story differs from unavailable supply; copy gives the actual reason.')
 if key in {'R17','D19','D20','D21','D22','O40','O41','O42','O43'}:return dict(asset='G05',motion=None,slot='Ticket/ledger edge outside amount and status',size='12 dp rim or 24 dp emblem',condition='No success spark for completed-but-unpaid work, claim processing, refund recording review or pending settlement.')
 if key in {'R18','R19','R20','R23','D23','D24'}:return dict(asset='G05',motion='M06' if key=='R18' else None,slot='Receipt/history illustration rim',size='12 dp rim; optional 48 dp header emblem',condition='Fare/status remain immediately visible; separate actual completed-payment acknowledgement may use M12 after approval.')
 if key in {'R21','S05','S07'}:return dict(asset='G24',motion='M12' if key!='S07' else None,slot='Small acknowledgement illustration',size='56–80 dp',condition='Only actual suitable response; privacy-preserving recovery acknowledgement remains neutral/static.')
 if key in {'R24','D26','R26','R27','R28','R29','D14','D27','D34','O44'}:return dict(asset='G15',motion='M05' if key=='R26' else None,slot='Schedule chapter / true empty upcoming list',size='24–40 dp header; 96 dp true-empty state',condition='Date/commitment and driver response windows are real text; no visual guaranteed assignment.')
 if key in {'D10','D12','D38'}:return dict(asset='G02',motion='M02' if key=='D10' else None,slot='Idle professional welcome/object region',size='96 dp idle; 32 dp online',condition='Car parks after entry; online state is not animated into existence; active work suppresses ambient motion.')
 if key in {'D13','D15','D41'}:return dict(asset='G21',motion=None,slot='Small static offer-header stripe',size='12–16 dp',condition='Pickup, fare/net and server timer have priority; no moving Accept/Decline targets.')
 if key in {'D29','D30','D37','A07','D04'}:return dict(asset='G20',motion=None,slot='Vehicle explanation header or silhouette fallback',size='56–96 dp',condition='Actual make/color/identifier stays separate; blueprint is not a vehicle photograph.')
 if key in {'D35','D00','D01'}:return dict(asset='G13',motion='M10' if key in {'D00'} else None,slot='Onboarding / membership explanation',size='80–112 dp',condition='Abstract people illustrate community; no invented membership or credential acceptance.')
 if prefix=='A' or key in {'D02','D03','D05','D06','D07','D36','O31','O32','O33','O34','O62','O78'}:return dict(asset='G12',motion='M07' if key in {'A04','A05','A06','D02','D03'} else None,slot='Application step chapter or true empty requirement state',size='32–64 dp; 96 dp empty',condition='Documents keep actual metadata/scan/evidence state; art never covers upload/retrieval/review fields.')
 if key in {'R33','R34','R35','D32'}:return dict(asset='G14',motion='M11' if key=='R33' else None,slot='General Help hub / true-empty own case',size='80–112 dp hub; 24 dp detail',condition='Warmth belongs to general help; safety/incident narratives use no playful graphic.')
 if key in {'S12','R30','R31','D28','S14'}:return dict(asset='G23' if key=='S12' else 'G07',motion='M16' if key=='S12' else None,slot='Small account chapter illustration / preference specimen',size='32–64 dp',condition='Appearance switch only where approved and delivered; credentials/profile data stay ordinary readable fields.')
 if prefix=='O':return dict(asset='G21',motion='M17' if key in {'O05','O06','O14','O17','O19','O21','O23','O27','O37','O45','O47','O60'} else None,slot='Cropped workspace chapter edge',size='16–24 dp; no pattern behind table/form text',condition='One entrance; selection, data rows and command controls remain stable; reduced motion immediate.')
 return dict(asset='G08',motion=None,slot='Small static section-corner ornament',size='16–24 dp',condition='Only outside text/control bounds; remove first at 200% text or a dense task.')
